prolog:
#Region }IDE.ReprocessFeeders
# ====================================================================================================
# }IDE.ReprocessFeeders -- reprocess one cube's feeders on the target server.
#
# WHO RUNS IT
#   The IDE, after a deploy: for every cube whose rules the release changed.
#   TM1 v11 has no REST ProcessFeeders action, so this is the TI fallback (the
#   same function the MCP reprocess_feeders tool uses).
#
# WHAT IT DOES
#   CubeProcessFeeders(pCube) -- rebuild the cube's feeder list from its rules.
#   A failure or an empty cube name fails this process, so the deploy reports
#   the cube as incomplete instead of pretending the feeders ran.
#
# SOURCE ti-processes/reprocess-feeders/process.json in the TM1 IDE repo. The
#        server copy is the runtime copy; the IDE creates it on demand.
# ====================================================================================================
#EndRegion
cThis = GetProcessName();
cCube = pCube;
IF(cCube @= '');
  LogOutput('ERROR', cThis | ': no cube name was passed');
  ProcessError;
ENDIF;
nStart = NOW();
CubeProcessFeeders(cCube);
nSeconds = (NOW() - nStart) * 86400;
LogOutput('INFO', cThis | ': feeders reprocessed for ' | cCube | ' in ' | NumberToString(nSeconds) | ' seconds');
